#include "iprop.h"
#include <new>
#include <cstdlib>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <vector>
static bool armed = false;
static unsigned fail_at = 0, allocations = 0, injected = 0;
void* operator new(std::size_t n) {
  if (armed && ++allocations == fail_at) { ++injected; throw std::bad_alloc(); }
  if (void* p = std::malloc(n?n:1)) return p;
  throw std::bad_alloc();
}
void* operator new[](std::size_t n) { return ::operator new(n); }
void operator delete(void* p) noexcept { std::free(p); }
void operator delete[](void* p) noexcept { std::free(p); }
static void escaped(const char* text) {
  std::putchar('"');
  for (;*text;++text) {
    if (*text=='"' || *text=='\\') { std::putchar('\\'); std::putchar(*text); }
    else if (*text=='\n') std::fputs("\\n",stdout);
    else std::putchar(*text);
  }
  std::putchar('"');
}
int main(int argc,char**argv) {
  if(argc!=4)return 2;
  std::ifstream file(argv[1],std::ios::binary);
  std::vector<unsigned char> bytes((std::istreambuf_iterator<char>(file)),{});
  if(std::strcmp(argv[2],"load-format-error")==0) bytes.assign({1,2,3});
  const bool loading=std::strncmp(argv[2],"load",4)==0;
  iprop_program* program=nullptr;
  iprop_result* result=nullptr;
  char err[128]="SENTINEL";
  iprop_generate_options options={};
  iprop_uniform uniform={};
  uniform.name="base";uniform.type=IPROP_UNIFORM_F32;
  int status=-1;bool crossed=false;
  if(std::strcmp(argv[2],"generate-type-error")==0) { options.uniforms=&uniform;options.uniform_count=1; }
  if(!loading && iprop_program_load(bytes.data(),bytes.size(),&program,err,sizeof(err))!=IPROP_OK)return 3;
  fail_at=static_cast<unsigned>(std::strtoul(argv[3],nullptr,10));
  armed=true;
  try {
    if(loading) status=int(iprop_program_load(bytes.data(),bytes.size(),&program,err,sizeof(err)));
    else status=int(iprop_generate(program,&options,&result,err,sizeof(err)));
  } catch(const std::bad_alloc&) { crossed=true; }
  armed=false;
  std::printf("{\"operation\":\"%s\",\"status\":%d,\"fail_at\":%u,\"allocations\":%u,\"injected\":%u,\"exception_crossed_c_boundary\":%s,\"out_null\":%s,\"err\":",argv[2],status,fail_at,allocations,injected,crossed?"true":"false",(loading?program!=nullptr:result!=nullptr)?"false":"true");
  escaped(err);std::puts("}");
  iprop_result_free(result);iprop_program_free(program);
  return 0;
}

